        assertThat(resp.getStatusCode().value()).isEqualTo(200);
        assertThat(lastMethod.get()).isEqualTo("POST");
        assertThat(lastPath.get()).isEqualTo("/fhir/Patient");
        assertThat(lastBody.get()).isEqualTo(body);
