        if (queryString == null || queryString.isBlank()) {
            return false;
        }
        for (String pair : queryString.split("&")) {
            String key = pair.contains("=") ? pair.substring(0, pair.indexOf('=')) : pair;
            if (key.equals(name)) {
                return true;
            }
        }
        return false;
    }
}

