                    + "{\"resource\":{\"resourceType\":\"MedicationRequest\",\"id\":\"5\"}},"
                    + "{\"resource\":{\"resourceType\":\"AllergyIntolerance\",\"id\":\"6\"}},"
                    + "{\"resource\":{\"resourceType\":\"Patient\",\"id\":\"7\"}}"
                    + "]}");

